describe('Stale Data Invalidation on Form Submission', () => {
  beforeEach(() => {
    cy.visit('/form-page');
  });

  it('should invalidate stale data after successful form submission', () => {
    // Intercept the API call to submit the form
    cy.intercept('POST', '/api/form/submit').as('formSubmit');

    // Fill in the form with stale data
    cy.get('[data-testid="name-input"]').type('John Doe');
    cy.get('[data-testid="email-input"]').type('john.doe@example.com');
    cy.get('[data-testid="phone-input"]').type('1234567890');

    // Verify stale data is displayed
    cy.get('[data-testid="name-input"]').should('have.value', 'John Doe');
    cy.get('[data-testid="email-input"]').should('have.value', 'john.doe@example.com');
    cy.get('[data-testid="phone-input"]').should('have.value', '1234567890');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API response
    cy.wait('@formSubmit');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'Form submitted successfully');

    // Verify stale data is cleared
    cy.get('[data-testid="name-input"]').should('have.value', '');
    cy.get('[data-testid="email-input"]').should('have.value', '');
    cy.get('[data-testid="phone-input"]').should('have.value', '');

    // Verify form is reset
    cy.get('[data-testid="name-input"]').should('be.disabled');
    cy.get('[data-testid="email-input"]').should('be.disabled');
    cy.get('[data-testid="phone-input"]').should('be.disabled');

    // Verify form is ready for new data
    cy.get('[data-testid="name-input"]').should('not.have.value');
    cy.get('[data-testid="email-input"]').should('not.have.value');
    cy.get('[data-testid="phone-input"]').should('not.have.value');
  });

  it('should handle form submission with invalid data and display error messages', () => {
    // Intercept the API call to submit the form
    cy.intercept('POST', '/api/form/submit').as('formSubmit');

    // Fill in the form with invalid data
    cy.get('[data-testid="name-input"]').type('');
    cy.get('[data-testid="email-input"]').type('invalid-email');
    cy.get('[data-testid="phone-input"]').type('');

    // Verify error messages are displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Name is required');
    cy.get('[data-testid="error-message"]').should('contain', 'Email is invalid');

    // Verify form fields are still visible
    cy.get('[data-testid="name-input"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="phone-input"]').should('be.visible');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API response
    cy.wait('@formSubmit');

    // Verify error messages are cleared
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify success message does not appear
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify form is still ready for new data
    cy.get('[data-testid="name-input"]').should('be.visible');
    cy.get('[data-testid="email-input"]').should('be.visible');
    cy.get('[data-testid="phone-input"]').should('be.visible');
  });
});
